// ---- HTTP Client with reqwest ----
// Add to Cargo.toml:
// [dependencies]
// reqwest = { version = "0.11", features = ["json"] }
// tokio = { version = "1.0", features = ["full"] }

use std::collections::HashMap;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Async HTTP Client ===");

    // ---- GET request ----
    let response = reqwest::get("https://httpbin.org/ip").await?;
    let body = response.text().await?;
    println!("GET response: {}", body);

    // ---- GET with headers ----
    let client = reqwest::Client::new();
    let response = client
        .get("https://httpbin.org/user-agent")
        .header("User-Agent", "Rust-chan")
        .send()
        .await?;
    let body = response.text().await?;
    println!("User-Agent response: {}", body);

    // ---- GET with query parameters ----
    let params = vec![("page", "1"), ("limit", "10")];
    let response = client
        .get("https://httpbin.org/get")
        .query(&params)
        .send()
        .await?;
    let body = response.text().await?;
    println!("Query params response: {}", body);

    // ---- POST with JSON ----
    let mut data = HashMap::new();
    data.insert("name", "Hero");
    data.insert("level", "5");

    let response = client
        .post("https://httpbin.org/post")
        .json(&data)
        .send()
        .await?;
    let body = response.text().await?;
    println!("POST response: {}", body);

    // ---- Error handling ----
    let result = client
        .get("https://httpbin.org/status/404")
        .send()
        .await;

    match result {
        Ok(resp) => println!("Status: {}", resp.status()),
        Err(e) => println!("Error: {}", e),
    }

    // ---- Parse JSON response ----
    #[derive(Debug, serde::Deserialize)]
    struct IpResponse {
        origin: String,
    }

    let response = client
        .get("https://httpbin.org/ip")
        .send()
        .await?;
    let ip_data: IpResponse = response.json().await?;
    println!("Your IP: {}", ip_data.origin);

    // ---- Timeout ----
    let result = client
        .get("https://httpbin.org/delay/3")
        .timeout(std::time::Duration::from_secs(1))
        .send()
        .await;

    match result {
        Ok(resp) => println!("Response: {:?}", resp),
        Err(e) => println!("Timeout error: {}", e),
    }

    Ok(())
}

